def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if budget <= 0:
        return 0.0

    if not alive:
        return float(min(budget, 18.0))

    prev_bids = []
    needy_count = 0
    rich_count = 0
    for opp in alive:
        if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
            needy_count += 1
        if opp.get('budget', 0) >= budget:
            rich_count += 1
        prev = opp.get('previous_trace', {})
        bid = prev.get('bid') if isinstance(prev, dict) else None
        if bid is not None:
            prev_bids.append(float(bid))

    max_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    contested = len(alive) + 1
    can_feed_two = supply >= WATER_REQ * 2
    can_feed_one = supply < WATER_REQ * 2

    if hp <= 2 or no_water >= 2:
        emergency = max(92.0, max_prev + 3.0)
        if can_feed_one:
            emergency = max(emergency, 108.0)
        return float(min(budget, emergency))

    if hp <= 4 or no_water >= 1:
        urgent = max(72.0, avg_prev * 0.82)
        if can_feed_one:
            urgent = max(urgent, max_prev + 2.0)
        return float(min(budget, urgent))

    if can_feed_two:
        base = 24.0
        if max_prev >= 140:
            base = 16.0
        elif max_prev >= 110:
            base = 20.0
        elif max_prev > 0:
            base = min(32.0, avg_prev * 0.28)
        if needy_count >= 2:
            base += 4.0
        if rich_count >= 2:
            base -= 2.0
        if day >= 8 and hp >= 5:
            base -= 3.0
        return float(max(0.0, min(budget, base)))

    base = 46.0
    if max_prev >= 140:
        base = 38.0
    elif max_prev >= 110:
        base = 42.0
    elif max_prev > 0:
        base = max(36.0, avg_prev * 0.4)

    if needy_count >= 2:
        base += 8.0
    if rich_count >= 2:
        base += 5.0
    if day <= 2:
        base += 4.0
    if day >= 8:
        base -= 4.0

    reserve_floor = DAILY_SALARY * max(0, 10 - day) * 0.18
    if budget < reserve_floor:
        base *= 0.82

    return float(max(0.0, min(budget, base)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.5)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    current_bid = float(DAILY_SALARY)

    if my_status['hp'] <= 2:
        current_bid = max(current_bid, DAILY_SALARY * 1.3)
    elif my_status['hp'] <= 4:
        current_bid = max(current_bid, DAILY_SALARY * 1.1)
    elif my_status['hp'] >= 8:
        current_bid = min(current_bid, DAILY_SALARY * 0.85)

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        if highest_prev_bid >= DAILY_SALARY * 1.2:
            current_bid = max(current_bid, highest_prev_bid + 5.0)
        elif highest_prev_bid >= DAILY_SALARY * 0.9:
            current_bid = max(current_bid, highest_prev_bid + 1.0)
        else:
            current_bid = max(current_bid, highest_prev_bid * 1.05)

    total_water_demand = WATER_REQ
    for opp in alive_opponents:
        total_water_demand += opp['water_requirement']

    supply_per_demand = day_context['supply'] / total_water_demand if total_water_demand > 0 else 1.0

    if supply_per_demand < 0.8:
        current_bid *= 1.15
    elif supply_per_demand < 1.0:
        current_bid *= 1.05
    elif supply_per_demand > 1.5:
        current_bid *= 0.9

    remaining_days = EPISODE_DAYS - day_context['day']
    if remaining_days <= 2:
        current_bid *= 1.15
    elif remaining_days <= 4:
        current_bid *= 1.05

    min_viable_bid = DAILY_SALARY * 0.1 
    current_bid = max(current_bid, min_viable_bid)

    return min(my_status['budget'], current_bid)

